<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/requestService.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);requireRole($user,['Student','Administrator']);
$id=filter_input(INPUT_GET,'request_id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Invalid ID');}$r=findRequestForUser($pdo,$id,$user);if(!$r){http_response_code(404);exit('Request not found.');}$topic=decodeTopic($r['topic']);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?>
<main class="container py-4"><h1>Edit request #<?=$id?></h1><?php if($r['status']!=='Open'):?><p>Only Open requests may be edited.</p><?php else:?>
<form method="post" action="/php/update-request.php"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="request_id" value="<?=$id?>"><label class="form-label">Course<select class="form-select mb-3" name="course"><?php foreach(['IS 6465','IS 6495','IS 6570'] as $c):?><option value="<?=escapeHtml($c)?>" <?=$c===$r['course']?'selected':''?>><?=escapeHtml($c)?></option><?php endforeach;?></select></label><label class="form-label">What would you like help with?<textarea class="form-control mb-3" name="reason" minlength="10" maxlength="500" required><?=escapeHtml($topic['reason'])?></textarea></label><label class="form-label">Preferred date<input class="form-control mb-3" name="preferreddate" type="date" value="<?=escapeHtml($r['preferred_date'])?>" required></label><fieldset><legend>Topics</legend><?php foreach(['Exam review','Practice problems','Study plan'] as $t):?><label class="me-3"><input type="checkbox" name="topics[]" value="<?=escapeHtml($t)?>" <?=in_array($t,$topic['topics'],true)?'checked':''?>> <?=escapeHtml($t)?></label><?php endforeach;?></fieldset><fieldset><legend>Preferred time</legend><?php foreach(['Morning','Afternoon','Evening'] as $t):?><label class="me-3"><input type="radio" name="preferredtime" value="<?=$t?>" <?=$t===$r['preferred_time']?'checked':''?> required> <?=$t?></label><?php endforeach;?></fieldset><button class="btn btn-primary mt-3">Save changes</button></form><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
